-- Modify "procurement_candidate_sets" table
ALTER TABLE "procurement_candidate_sets" ADD CONSTRAINT "chk_pcs_external_lane_status" CHECK (external_lane_status = ANY (ARRAY['PENDING'::text, 'RUNNING'::text, 'SUCCEEDED'::text, 'FAILED'::text, 'SKIPPED'::text, 'CANCELLED'::text])), ADD CONSTRAINT "chk_pcs_failure_reason" CHECK ((failure_reason = ''::text) OR (failure_reason = ANY (ARRAY['WORKER_LOST'::text, 'LANE_ALL_FAILED'::text]))), ADD CONSTRAINT "chk_pcs_platform_lane_status" CHECK (platform_lane_status = ANY (ARRAY['PENDING'::text, 'RUNNING'::text, 'SUCCEEDED'::text, 'FAILED'::text, 'SKIPPED'::text, 'CANCELLED'::text])), ADD CONSTRAINT "chk_pcs_status" CHECK (status = ANY (ARRAY['QUEUED'::text, 'RUNNING'::text, 'WAITING_FOR_INPUT'::text, 'CANCEL_REQUESTED'::text, 'SUCCEEDED'::text, 'FAILED'::text, 'CANCELLED'::text, 'RESUMED'::text, 'EXPIRED'::text]));
